const payments = {
  esewa: {
    name: 'eSewa',
    description: 'Scan the QR code with eSewa or use my eSewa mobile number.',
    detail: 'eSewa · 9866805775',
    copy: '9866805775',
    copyLabel: 'Copy eSewa ID',
    href: 'https://esewa.com.np/',
    button: 'Open eSewa',
  },
  khalti: {
    name: 'Khalti',
    description: 'Scan the QR code with Khalti or use my Khalti mobile number.',
    detail: 'Khalti · 9866805775',
    copy: '9866805775',
    copyLabel: 'Copy Khalti ID',
    href: 'https://khalti.com/',
    button: 'Open Khalti',
  },
  bank: {
    name: 'Bank Transfer',
    description: 'Transfer directly to my Global IME Bank account or scan the QR code.',
    detail: 'Global IME Bank',
    copy: '19507010129350',
    copyLabel: 'Copy Account Number',
    href: 'https://www.globalimebank.com/',
    button: 'Open Global IME Bank',
  },
} as const;

export default function SupportSection() {
  const [open, setOpen] = useState<PaymentMethod>(null);
  const [copied, setCopied] = useState<PaymentMethod>(null);

  const toggle = (method: Exclude<PaymentMethod, null>) => {
    setOpen((current) => (current === method ? null : method));
    setCopied(null);
  };

  const copyPayment = async (
    method: Exclude<PaymentMethod, null>,
    value: string,
  ) => {
    try {
      await navigator.clipboard.writeText(value);
      setCopied(method);
      window.setTimeout(() => setCopied(null), 1600);
    } catch {
      window.prompt('Copy this payment ID:', value);
    }
  };

  return (
    <section id="support" className="support-section">
      <div className="support-shell">
        <div className="support-hero">
          <div className="support-copy">
            <span className="support-eyebrow">SUPPORT MY WORK</span>
            <h2>Keep me <span>building.</span> ☕</h2>
            <p className="support-lead">
              If you enjoy my projects, experiments or learning journey, you can
              support future builds. Choose your preferred Nepal payment method below.
            </p>
            <div className="support-trust">
              <span><ShieldCheck size={14} /> Secure provider checkout</span>
              <span><Smartphone size={14} /> Nepal payment options</span>
              <span><Code2 size={14} /> Developer-built</span>
            </div>
          </div>
        </div>

        <div className="support-options">
          <div className="support-intro">
            <span className="support-eyebrow">SUPPORT ME</span>
            <h3>Choose a payment method</h3>
            <p>Select a payment option to reveal the QR code and payment details.</p>
          </div>

          <div className="support-provider-grid">
            {(['esewa', 'khalti', 'bank'] as const).map((method) => {
              const payment = payments[method];
              const isOpen = open === method;
              const isCopied = copied === method;

              return (
                <article
                  key={method}
                  className={`support-card support-${method} ${isOpen ? 'is-open' : ''}`}
                >
                  <button
                    className="support-trigger"
                    type="button"
                    aria-expanded={isOpen}
                    onClick={() => toggle(method)}
                  >
                    <span className="support-provider-logo">
                      {method === 'esewa' ? 'e' : method === 'khalti' ? 'K' : <Building2 size={22} />}
                    </span>
                    <span className="support-method-copy">
                      <span>PAYMENT OPTION</span>
                      <strong>{payment.name}</strong>
                      <small>
                        {isOpen ? 'Tap to close payment details' : 'Tap to view QR & payment details'}
                      </small>
                    </span>
                    <ChevronDown
                      className={`support-chevron ${isOpen ? 'is-open' : ''}`}
                      size={19}
                      aria-hidden="true"
                    />
                  </button>

                  <div className={`support-details ${isOpen ? 'is-visible' : ''}`}>
                    <p>{payment.description}</p>
                    <div className="support-qr-stage">
                      <div className="support-qr-info" role="status">
                        <span>PAYMENT DETAILS</span>
                        <strong>Pratik Poudel</strong>
                        <b>{payment.detail}</b>
                        {method === 'bank' && <b className="support-account-number">{payment.copy}</b>}
                        <button
                          className="support-copy-button"
                          type="button"
                          onClick={() => copyPayment(method, payment.copy)}
                        >
                          {isCopied ? <Check size={15} /> : <Clipboard size={15} />}
                          {isCopied ? 'Copied' : payment.copyLabel}
                        </button>
                      </div>

                      <div className="support-qr-box">
                        <img
                          src={qrImages[method]}
                          alt={`${payment.name} payment QR code for Pratik Poudel`}
                          loading="lazy"
                        />
                      </div>

                      <span className="support-qr-caption">
                        <QrCode size={14} /> Hover or tap the QR to see payment details
                      </span>
                    </div>

                    <a
                      className="support-provider-button"
                      href={payment.href}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      <ArrowUpRight size={15} /> {payment.button}
                    </a>
                  </div>
                </article>
              );
            })}
          </div>

          <div className="support-note">
            <Hand size={22} />
            <div>
              <strong>One step at a time</strong>
              <p>Choose a payment method first. The QR code and details appear when you open it.</p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
